insert into public.pages (id, slug, title, seo_title, seo_description, status, is_system, sort_order) values
  ('9e36afb6-9da0-5bf9-91f6-c860dbce5e93', 'home', 'Home', null, 'VoltageAfrica is building intelligent renewable energy infrastructure to expand rural electricity access, power productive communities, and connect the future of energy in Africa.', 'published', true, 0),
  ('57afc7f2-cd59-5596-b56c-026349473064', 'vision', 'Our vision', 'Our vision', 'The energy access challenge in rural Africa and VoltageAfrica''s long-term vision: from community microgrids to a distributed energy network.', 'published', true, 1),
  ('38874e54-bcba-5aec-b8b7-a540a667ba66', 'technology', 'Technology', 'Technology', 'How VoltageAfrica''s solar microgrids work: generation, storage, intelligent energy management and productive-use energy.', 'published', true, 2),
  ('65166520-c7eb-51d2-a894-956d912d7e2a', 'pilot', 'The Shurugwi pilot', 'The Shurugwi pilot', 'VoltageAfrica''s proposed first pilot hub in Shurugwi, Midlands, Zimbabwe: community research, the proposed hub and the pilot development stages.', 'published', true, 3),
  ('e4b91eb5-e756-5fcf-b122-800948b15f5c', 'journey', 'Our journey', 'Our journey', 'VoltageAfrica''s journey: prototypes, community research, recognition and the road to the first pilot hub.', 'published', true, 4),
  ('a19ff43f-39ec-5161-881c-8f71f4dfc961', 'impact', 'Impact & recognition', 'Impact & recognition', 'Press coverage, awards and community impact: VoltageAfrica in The Herald, BRICS+, Global HackAtom, Green Generation Initiative and more.', 'published', true, 5),
  ('3b1ab4fd-6c30-5c31-be01-bf4c3ebb71fd', 'about', 'About', 'About', 'About VoltageAfrica: founder Sean Mavhima, the team, and the principles that guide how we build energy infrastructure.', 'published', true, 6),
  ('177bd0af-7d32-5472-9ca6-987f58ab3492', 'contact', 'Contact & partnerships', 'Contact & partnerships', 'Partner with VoltageAfrica: energy, technology, development, investment, research and agricultural partners.', 'published', true, 7),
  ('894da38a-92f3-5bc8-b4a0-2e05ad3d58ac', 'partner', 'Partner with us', 'Partner with us', 'Partner with VoltageAfrica: energy companies, NGOs, governments, investors, universities, technology and equipment suppliers working towards accessible, intelligent and sustainable energy infrastructure.', 'published', true, 9),
  ('a47afd98-427b-5847-a284-c50905ae7ba8', 'support', 'Support VoltageAfrica', 'Support VoltageAfrica', 'Support VoltageAfrica''s mission with funding, equipment, technical expertise or institutional support, from community energy pilots to battery storage and productive-use solutions.', 'published', true, 10),
  ('2abe12b1-b67f-515b-b8e6-86aed89cabc7', 'press', 'Funders & press', 'Funders & press', 'VoltageAfrica for funders, programme officers and journalists: key facts, research report, logos, photographs and ready-to-use descriptions.', 'published', true, 11),
  ('27e84d58-5765-5bd3-b317-d34fbbb13a58', 'energy-lab', 'AI Energy Lab', 'AI Energy Lab', 'VoltageAfrica''s AI Energy Lab: an interactive, simulated community microgrid. Explore energy flows, run what-if scenarios, compare intelligent management with an uncontrolled system, and ask the energy copilot. All data is simulated.', 'published', true, 13),
  ('caf6303d-2ba8-5e37-a3fc-19af3cd1b340', 'privacy', 'Privacy policy', 'Privacy policy', 'How VoltageAfrica collects, uses and protects personal information submitted through this website.', 'published', true, 12),
  ('b2788bf2-d776-593b-9094-8b6941794b8b', 'projects', 'Projects', 'Projects', 'VoltageAfrica''s projects: from the Shurugwi pilot hub to future community energy initiatives.', 'published', true, 8)
insert into public.page_sections (id, page_id, type, label, content, settings, status, is_visible, sort_order) values
  ('23fbf37c-1176-59e3-b0a8-a8de2cd7614f', '9e36afb6-9da0-5bf9-91f6-c860dbce5e93', 'hero', null, '{"kicker":"Intelligent energy infrastructure · Zimbabwe","headline":"Africa’s next grid will be built *from the village up.*","body":"VoltageAfrica designs intelligent solar microgrids (generation, storage and the software that runs them) for the communities the national grid has not reached. Our first hub is being prepared in Shurugwi, in Zimbabwe’s Midlands.","primaryCta":{"label":"Explore our vision","href":"/vision"},"secondaryCta":{"label":"Partner with us","href":"/partner"},"image":{"id":"b39ec6d7-77ee-5855-ac7f-ad216a284d84","src":"/images/landscape/matobo-view.jpg","alt":"Sunlight breaking through a rain storm over the granite kopjes and woodland of the Matobo Hills, Zimbabwe"},"scenes":[{"image":{"id":"b39ec6d7-77ee-5855-ac7f-ad216a284d84","src":"/images/landscape/matobo-view.jpg","alt":"Sunlight breaking through a rain storm over the granite kopjes and woodland of the Matobo Hills, Zimbabwe"},"title":"The land","caption":"Light through a storm over the Matobo Hills, Zimbabwe.","position":"50% 55%","motion":"in"},{"image":{"id":"832709ee-0938-5546-a656-1d4d78197041","src":"/images/outreach/kigali-courtyard.jpg","alt":"Students and teachers gathered outside a brick school building in Kigali after a VoltageAfrica lesson"},"title":"The people","caption":"Students and teachers after a VoltageAfrica climate education session in Kigali, Rwanda.","position":"50% 62%","motion":"right"},{"image":{"id":"fcba3f86-e401-563f-bced-08d57df88df7","src":"/images/commons/mini-grid-bayelsa.jpg","alt":"Aerial view of a fenced solar mini-grid with rows of panels and a small power house, beside forest, a river and a town in Bayelsa, Nigeria"},"title":"The energy","caption":"A solar mini-grid serving a community in Bayelsa, Nigeria. Not a VoltageAfrica installation.","position":"66% 66%","motion":"left"},{"image":{"id":"02540fe5-f430-5c65-b686-24dce1be83a6","src":"/images/commons/battery-storage-schwerin.jpg","alt":"Long aisles of battery racks and control cabinets inside the WEMAG battery storage hall in Schwerin, Germany"},"title":"The intelligence","caption":"Battery racks under continuous computer control at the WEMAG storage plant, Schwerin, Germany. Not a VoltageAfrica installation.","position":"50% 50%","motion":"in"},{"image":{"id":"65fa27c4-697d-5cc2-90ea-930dfb71eeaf","src":"/images/commons/golden-sunset-kampala.jpg","alt":"The sun setting behind the silhouette of a great spreading tree, with warm golden light, in Kawempe, Kampala, Uganda"},"title":"The future","caption":"Golden sunset in Kawempe, Kampala, Uganda.","position":"56% 52%","motion":"out"}],"sceneDuration":8,"enable3d":true,"defaultMode":"film","overlay":55,"showScrollCue":false}'::jsonb, '{}'::jsonb, 'published', true, 0),
  ('4be3883c-fcfb-5b07-869d-f52fae7ace73', '9e36afb6-9da0-5bf9-91f6-c860dbce5e93', 'key_facts', 'At a glance', '{"kicker":"At a glance","headline":"","items":[{"label":"First pilot hub","value":"In preparation","detail":"Shurugwi, Midlands Province, Zimbabwe. Not yet operational.","href":"/pilot"},{"label":"Community research","value":"5 villages","detail":"23 household interviews, 6 community leaders and 27 surveys (May 2025).","href":"/documents/voltageafrica-shurugwi-validation-report-2025.pdf"},{"label":"Prototype","value":"Built & tested","detail":"Sun-tracking rig: four 15 W modules steered by a light sensor (2025).","href":"/technology#approach"},{"label":"Team","value":"4 people","detail":"Working across Zimbabwe, Rwanda and Kenya.","href":"/about"},{"label":"Recognition","value":"5 awards","detail":"Prizes and selections, including 2nd place at the BRICS+ Youth Innovation Summit 2026.","href":"/impact#awards"},{"label":"Building since","value":"2024","detail":"From an energy-trading prototype to field research and hardware.","href":"/journey"}],"note":""}'::jsonb, '{"anchor":"at-a-glance"}'::jsonb, 'published', true, 1),
  ('8358febe-6790-5f4a-addf-51b194b55179', '9e36afb6-9da0-5bf9-91f6-c860dbce5e93', 'act', 'Act I · The reality', '{"layout":"reality","numeral":"I","kicker":"The reality","headline":"When night falls across rural Africa, *opportunity switches off.*","body":"Without reliable electricity, children study by candlelight, clinics cannot keep vaccines cold, and small businesses close at dusk. Scarce household income goes on kerosene, candles, firewood and paying someone else to charge a phone.","image":{"id":"bb75451a-ffc4-5e7a-9d96-c828dc31260c","src":"/images/landscape/chidoma-dusk.jpg","alt":"Chidoma Kopje and the Mapfungautsi Plateau rendered in deep dusk tones"},"imageCaption":"Chidoma Kopje beside the Mapfungautsi Plateau, Midlands Province, Zimbabwe (tonally treated).","imagePosition":"50% 60%","stats":[{"value":"600","unit":"million","label":"people in Africa lived without electricity in 2021: 43% of the continent''s population.","source":"IEA, Africa Energy Outlook 2022","sourceUrl":"https://www.iea.org/reports/africa-energy-outlook-2022/key-findings"},{"value":"23.4","unit":"%","label":"of rural residents in Zimbabwe have access to grid electricity, against 87.4% in urban areas.","source":"ZimStat 2022 Population & Housing Census, as reported by DevelopmentAid","sourceUrl":"https://www.developmentaid.org/news-stream/post/189995/electricity-access-in-rural-zimbabwe"},{"value":"970","unit":"million","label":"Africans lack access to clean cooking, relying on wood, charcoal and kerosene.","source":"IEA, Africa Energy Outlook 2022","sourceUrl":"https://www.iea.org/reports/africa-energy-outlook-2022/key-findings"}]}'::jsonb, '{"anchor":"reality"}'::jsonb, 'published', true, 2),
  ('882c789b-fd9f-525f-a454-da2d03480762', '9e36afb6-9da0-5bf9-91f6-c860dbce5e93', 'act', 'Act II · The idea', '{"layout":"split","numeral":"II","kicker":"The idea","headline":"Start with one community. *Build the system it actually needs.*","body":"VoltageAfrica designs complete local energy systems (generation, storage, intelligence and distribution) around the homes, schools and enterprises they serve. We began by listening, then by building.","image":{"id":"e24fa183-d39e-5832-a4ec-963c2187bdc4","src":"/images/prototype/tracker-array.jpg","alt":"VoltageAfrica''s prototype: four solar modules arranged around a central light-sensor module"},"imageCaption":"VoltageAfrica’s sun-tracking prototype, 2025: four 15 W modules steered by a central light sensor.","imagePosition":"50% 50%","images":[{"image":{"id":"9312dba9-831c-5676-a6ce-340875d38954","src":"/images/founder/sean-field.jpg","alt":"Sean Mavhima planting a tree in dense green bush"},"caption":"Sean Mavhima, founder, in the field."}],"points":[{"title":"Listen first","body":"23 household interviews, 6 community leaders and 27 surveys across five Shurugwi villages in May 2025."},{"title":"Prototype and measure","body":"A sun-tracking rig of four 15 W modules, built and tested in 2025."},{"title":"Design for productive use","body":"Hubs sized around mills, pumps and cold rooms as well as homes, because income is what makes energy access last."}],"cta":{"label":"Our approach","href":"/technology#approach"}}'::jsonb, '{"anchor":"idea"}'::jsonb, 'published', true, 3),
  ('ce116db1-a19b-56c0-b8a5-27ab3641d123', '9e36afb6-9da0-5bf9-91f6-c860dbce5e93', 'microgrid_exhibit', null, '{"kicker":"Act III · The system","headline":"Inside a VoltageAfrica *microgrid.*","intro":"A working model of a community energy hub. Orbit it, select any part to see what it does, and run a full day to watch solar, storage and demand balance each other.","cta":{"label":"Enter the full-screen exhibit","href":"/microgrid"},"disclaimer":"Conceptual model for explanation only. It does not depict an existing VoltageAfrica installation, and all values are simulated."}'::jsonb, '{"anchor":"microgrid"}'::jsonb, 'published', true, 4),
  ('5faaba5f-c820-5ea3-bd35-c0fff74e9e77', '9e36afb6-9da0-5bf9-91f6-c860dbce5e93', 'act', 'Act IV · The intelligence', '{"layout":"register","numeral":"IV","kicker":"The intelligence","headline":"An intelligence layer, *stated honestly.*","body":"Monitoring, metering and control come first. Forecasting and optimisation follow once a live hub produces real operating data. Here is exactly where each capability stands today.","cta":{"label":"How the technology works","href":"/technology#intelligence"},"note":"We do not yet operate AI systems in any community. Statuses are updated as work progresses."}'::jsonb, '{"anchor":"intelligence"}'::jsonb, 'published', true, 5),
  ('437b3c3f-ecde-5751-a794-f135697ff932', '9e36afb6-9da0-5bf9-91f6-c860dbce5e93', 'act', 'Act V · The impact', '{"layout":"mosaic","numeral":"V","kicker":"The impact","headline":"Electricity is not the end goal. *It is the foundation.*","body":"Light for evening study. Cold storage for medicines and harvests. Power for the mill, the pump and the workshop. Energy matters for what it lets people do.","images":[{"image":{"id":"fe4ed70e-7393-5701-a6bb-6e6537ff5e24","src":"/images/outreach/kigali-classroom.jpg","alt":"A class gathered after a conservation and renewable energy lesson"},"caption":"A class after a VoltageAfrica conservation and renewable energy lesson, Kigali."},{"image":{"id":"3bda21c7-d6c8-5587-8107-99ab13439e22","src":"/images/milestones/green-generation-planting.jpg","alt":"Sean Mavhima and fellow participants tree planting with the Green Generation Initiative"},"caption":"Tree planting with the Green Generation Initiative."},{"image":{"id":"df03f173-41d0-595e-aae9-358cc22e559d","src":"/images/outreach/kigali-school-group.jpg","alt":"Students and the VoltageAfrica team outside a classroom after a renewable energy lesson in Kigali"},"caption":"Students and the team after a lesson in Kigali."}],"points":[{"title":"Evening study","body":"Light that lets learning continue after sunset, without candles or kerosene smoke."},{"title":"Health","body":"Refrigeration for vaccines and medicines, and power for basic clinical equipment."},{"title":"Water","body":"Pumping and irrigation that turn a single rainy season into year-round growing."},{"title":"Enterprise","body":"Milling, welding, tailoring, cold storage: the machines that make local income possible."},{"title":"Connection","body":"Phone charging and mobile money: access to markets, information and family."},{"title":"Forests","body":"Less pressure on woodland where firewood is the only fuel a household can reach."}],"note":"What reliable energy makes possible, as described in our community research. VoltageAfrica will publish measured impact once its first hub is operating."}'::jsonb, '{"anchor":"impact"}'::jsonb, 'published', true, 6),
  ('0453b8b1-0853-5e1f-887a-63e37491d47d', '9e36afb6-9da0-5bf9-91f6-c860dbce5e93', 'future', null, '{"kicker":"Act VI · The ambition","headline":"One village today. *A network tomorrow.*","intro":"Every hub we build is designed to connect with the next. Over time, many small, intelligent microgrids can work together as a distributed energy network and, eventually, as a virtual power plant.","stages":[{"title":"Community microgrids","horizon":"Now: preparing the first pilot","body":"Solar, storage and distribution serving a single community. The Shurugwi pilot hub is our first."},{"title":"Intelligent energy management","horizon":"Next","body":"Monitoring, metering and forecasting that let each hub run more efficiently and affordably."},{"title":"Connected energy assets","horizon":"Next phase","body":"Batteries, inverters, meters and productive equipment reporting into one platform."},{"title":"Distributed energy network","horizon":"Later","body":"Neighbouring microgrids able to share energy, so surplus in one community supports another."},{"title":"Virtual power plant","horizon":"Long-term vision","body":"Many distributed assets coordinated as one flexible resource that supports the wider grid. This is where we are heading. We do not operate one today."}]}'::jsonb, '{"anchor":"ambition"}'::jsonb, 'published', true, 7),
  ('b9bdd9d2-bb71-5060-8a7c-c5b22bd6e5db', '9e36afb6-9da0-5bf9-91f6-c860dbce5e93', 'act', 'Act VII · Invitation', '{"layout":"invitation","numeral":"VII","kicker":"Invitation","headline":"Let’s build what *comes next.*","body":"We are preparing our first pilot and looking for people and organisations who want to help build intelligent energy infrastructure for rural Africa.","image":{"id":"13a82779-6173-559c-9c15-bbad4f9e1462","src":"/images/renders/hub-dusk.jpg","alt":"Illustrative 3D render: a rural community at dusk with lit windows and power lines under an orange afterglow"},"imageCaption":"Illustrative render of a connected community at dusk. A vision, not an existing installation.","imagePosition":"50% 50%","links":[{"title":"Partner with us","body":"Collaborate on engineering, equipment, research, funding or community implementation.","href":"/partner"},{"title":"Support our work","body":"Offer funding, equipment, technical expertise or institutional support.","href":"/support"},{"title":"Contact us","body":"Media, speaking invitations, volunteering, careers or a general question.","href":"/contact"}]}'::jsonb, '{"anchor":"get-involved"}'::jsonb, 'published', true, 8),
  ('d2b33548-6060-505f-b654-b5641b6ff0f2', '57afc7f2-cd59-5596-b56c-026349473064', 'page_intro', null, '{"kicker":"Our vision","headline":"Energy is where *possibility begins.*","intro":"Why reliable electricity matters for rural Africa, and the distributed energy future VoltageAfrica is building toward, one connected community at a time.","index":[{"label":"The energy access challenge","anchor":"challenge"},{"label":"The future of energy","anchor":"future"}],"image":{"id":"0f2d8eb6-a385-5ce3-a333-c0000614f073","src":"/images/outreach/kigali-lesson-group.jpg","alt":"Secondary-school students standing with the VoltageAfrica team in front of a projected slide reading ''We need to treat Earth with respect''"},"imageCaption":"A VoltageAfrica renewable energy and conservation lesson with secondary-school students in Kigali, Rwanda.","imagePosition":"50% 45%"}'::jsonb, '{}'::jsonb, 'published', true, 0),
  ('c41adb89-5b08-57ac-9671-6584208bb3e8', '57afc7f2-cd59-5596-b56c-026349473064', 'challenge', null, '{"kicker":"The energy access challenge","interlude":"When night falls across rural Africa, *opportunity switches off.*","body":"Without reliable electricity, children study by candlelight, clinics cannot keep vaccines cold, and small businesses close at dusk. Scarce household income goes on kerosene, candles, firewood and paying someone else to charge a phone.","image":{"id":"bb75451a-ffc4-5e7a-9d96-c828dc31260c","src":"/images/landscape/chidoma-dusk.jpg","alt":"Chidoma Kopje and the Mapfungautsi Plateau rendered in deep dusk tones"},"stats":[{"value":"600","unit":"million","label":"people in Africa lived without electricity in 2021: 43% of the continent''s population.","source":"IEA, Africa Energy Outlook 2022","sourceUrl":"https://www.iea.org/reports/africa-energy-outlook-2022/key-findings"},{"value":"23.4","unit":"%","label":"of rural residents in Zimbabwe have access to grid electricity, against 87.4% in urban areas.","source":"ZimStat 2022 Population & Housing Census, as reported by DevelopmentAid","sourceUrl":"https://www.developmentaid.org/news-stream/post/189995/electricity-access-in-rural-zimbabwe"},{"value":"970","unit":"million","label":"Africans lack access to clean cooking, relying on wood, charcoal and kerosene.","source":"IEA, Africa Energy Outlook 2022","sourceUrl":"https://www.iea.org/reports/africa-energy-outlook-2022/key-findings"},{"value":"2.9","unit":"million","label":"deaths a year worldwide are attributed to household air pollution from solid fuels and kerosene.","source":"World Health Organization, 2021 data","sourceUrl":"https://www.who.int/news-room/fact-sheets/detail/household-air-pollution-and-health"}],"beyondKicker":"Why it matters beyond lighting","beyondTitle":"Electricity is not the end goal. It is the foundation everything else is built on.","beyond":[{"title":"Evening study","body":"Light that lets learning continue after sunset, without candles or kerosene smoke."},{"title":"Health","body":"Refrigeration for vaccines and medicines, and power for basic clinical equipment."},{"title":"Water","body":"Pumping and irrigation that turn a single rainy season into year-round growing."},{"title":"Enterprise","body":"Milling, welding, tailoring, cold storage: the machines that make local income possible."},{"title":"Connection","body":"Phone charging and mobile money: access to markets, information and family."},{"title":"Forests","body":"Less pressure on woodland where firewood is the only fuel a household can reach."}]}'::jsonb, '{"anchor":"challenge"}'::jsonb, 'published', true, 1),
  ('5d313c77-e3e7-5b44-970b-4f58cdea4e34', '57afc7f2-cd59-5596-b56c-026349473064', 'future', null, '{"kicker":"The future of energy","headline":"One village today. *A network tomorrow.*","intro":"Every hub we build is designed to connect with the next. Over time, many small, intelligent microgrids can work together as a distributed energy network and, eventually, as a virtual power plant.","stages":[{"title":"Community microgrids","horizon":"Now: preparing the first pilot","body":"Solar, storage and distribution serving a single community. The Shurugwi pilot hub is our first."},{"title":"Intelligent energy management","horizon":"Next","body":"Monitoring, metering and forecasting that let each hub run more efficiently and affordably."},{"title":"Connected energy assets","horizon":"Next phase","body":"Batteries, inverters, meters and productive equipment reporting into one platform."},{"title":"Distributed energy network","horizon":"Later","body":"Neighbouring microgrids able to share energy, so surplus in one community supports another."},{"title":"Virtual power plant","horizon":"Long-term vision","body":"Many distributed assets coordinated as one flexible resource that supports the wider grid. This is where we are heading. We do not operate one today."}]}'::jsonb, '{"anchor":"future"}'::jsonb, 'published', true, 2),
  ('91acfc92-be06-5af4-890e-53cae416ce2a', '57afc7f2-cd59-5596-b56c-026349473064', 'next_page', null, '{"kicker":"Next","title":"Technology","line":"How a VoltageAfrica microgrid works.","href":"/technology"}'::jsonb, '{}'::jsonb, 'published', true, 3),
  ('65ec905b-faba-5de0-a362-331802f173c6', '38874e54-bcba-5aec-b8b7-a540a667ba66', 'page_intro', null, '{"kicker":"Technology","headline":"How a VoltageAfrica *microgrid works.*","intro":"Generation, storage, intelligence and distribution designed as one system, and built around the enterprises and institutions it powers.","index":[{"label":"Our approach","anchor":"approach"},{"label":"Intelligent energy","anchor":"intelligence"},{"label":"Productive energy","anchor":"productive"}],"image":{"id":"e24fa183-d39e-5832-a4ec-963c2187bdc4","src":"/images/prototype/tracker-array.jpg","alt":"VoltageAfrica''s prototype: four solar modules arranged around a central light-sensor module"},"imageCaption":"VoltageAfrica’s sun-tracking prototype, 2025: four 15 W solar modules steered by a central light sensor.","imagePosition":"50% 55%"}'::jsonb, '{}'::jsonb, 'published', true, 0),
  ('818e11cb-e148-5236-8a23-9b0d02c2b105', '38874e54-bcba-5aec-b8b7-a540a667ba66', 'approach', null, '{"kicker":"Our approach","headline":"From sunlight to livelihoods, *one connected system.*","intro":"A VoltageAfrica microgrid is a complete local power system: it generates, stores, manages and delivers electricity where the national grid does not reach.","figureImage":{"id":"a4d45c5a-fa2a-5387-9d34-b231c9a3ad6e","src":"/images/prototype/tracker-sensor.jpg","alt":"VoltageAfrica''s sun-tracking prototype: four 15 W solar modules around a light-dependent-resistor sensor module"},"figureCaption":"VoltageAfrica’s sun-tracking prototype: four 15 W modules steered by a light sensor.","figureYear":"2025"}'::jsonb, '{"anchor":"approach"}'::jsonb, 'published', true, 1),
  ('e2c10497-9bcb-5ae0-92c4-8c4c0f5f21e7', '38874e54-bcba-5aec-b8b7-a540a667ba66', 'intelligence', null, '{"kicker":"Intelligent energy","headline":"Energy that *knows itself.*","intro":"Generating power is half the job. Keeping a remote microgrid reliable and affordable for years means measuring everything, anticipating demand and catching faults early. That is the software layer we are building toward.","disclaimer":"Illustrative model of a conceptual community hub (24 kW solar, 60 kWh storage). Values are generated by a simulation for demonstration. They are not live data and not a VoltageAfrica system specification.","registerTitle":"What exists today, and what comes next.","footnote":"We do not yet operate AI systems in any community. Forecasting and optimisation depend on real operating data, which the first pilot hub will begin to generate.","labCta":{"label":"Open the AI Energy Lab","href":"/energy-lab"}}'::jsonb, '{"anchor":"intelligence"}'::jsonb, 'published', true, 2),
  ('0849167f-0dce-5ba7-b59e-3b4ffab49965', '38874e54-bcba-5aec-b8b7-a540a667ba66', 'productive', null, '{"kicker":"Productive energy","headline":"Energy that *earns its keep.*","intro":"A light bulb improves an evening. A pump, a mill or a cold room changes an economy. We design every hub around the businesses and farms it can power, because that is what makes energy access last.","chain":[{"title":"kWh","body":"Reliable daytime power"},{"title":"Machine","body":"Pump, mill, freezer, tools"},{"title":"Product","body":"Water, flour, fresh produce"},{"title":"Income","body":"Sold locally, at better prices"}],"revenueKicker":"Business model · evolving","revenueTitle":"Households are where we start. *Productive use is how hubs become sustainable.*","revenue":[{"title":"Household energy","body":"Pay-as-you-go access for homes. Households in our Shurugwi research indicated they could pay up to about US$10 a month."},{"title":"Productive-use energy","body":"Our second revenue stream in development: supplying businesses and agriculture, and offering energy-efficient equipment such as pumps, mills and cold rooms."},{"title":"Institutional contracts","body":"Longer-term energy agreements with schools, clinics and public institutions that need reliable power."}]}'::jsonb, '{"anchor":"productive"}'::jsonb, 'published', true, 3),
  ('c5c81074-5788-547e-b980-462723f99f8a', '38874e54-bcba-5aec-b8b7-a540a667ba66', 'next_page', null, '{"kicker":"Next","title":"The microgrid exhibit","line":"Explore an interactive 3D model of a community energy hub.","href":"/microgrid"}'::jsonb, '{}'::jsonb, 'published', true, 4),
  ('c71d0e7a-97da-5d69-a549-bdf42e2898a6', '65166520-c7eb-51d2-a894-956d912d7e2a', 'pilot', null, '{"kicker":"The Shurugwi pilot","headline":"From vision *to village.*","status":"In preparation · not yet operational","intro":"Our first pilot hub is planned for Shurugwi, in Zimbabwe’s Midlands Province: a granite-kopje landscape of farming villages where many households still live without grid electricity. It is where our field research began.","villages":["Zura","Chinderera","Chinho","Mapako","Madungwe"],"diagramCaption":"Conceptual diagram · not geographic · not to scale","researchTitle":"What we have already done · May 2025","research":[{"value":"5","label":"villages engaged through local leadership"},{"value":"23","label":"household interviews, in person and virtual"},{"value":"6","label":"community leaders interviewed"},{"value":"27","label":"surveys completed, of 30 distributed"}],"heardTitle":"What communities told us","heard":[{"text":"Households said they could pay for energy on a pay-as-you-go basis, at up to about US$10 a month."},{"text":"Communities prefer a shared, community-owned energy hub to buying individual home systems."},{"text":"Strong interest in USSD payments, which work on basic phones without data."},{"text":"Support for clean cooking alongside electricity: firewood dependence is driving deforestation."},{"text":"Schools visited, including Chinho Primary School, were interested in off-grid solar."}],"note":"Three village leaders gave verbal support for a future partnership.","hubTitle":"The proposed hub","hubNote":"Concept · specifications follow site assessment","hub":[{"title":"Solar array","body":"Ground-mounted generation sized to measured community demand."},{"title":"Battery storage","body":"Evening and overnight supply, with reserve for cloudy days."},{"title":"Household connections","body":"Metered, pay-as-you-go access for homes."},{"title":"Community institutions","body":"Schools such as Chinho Primary School, which expressed interest."},{"title":"Productive use","body":"Milling, irrigation or cold storage as anchor loads."}],"stagesTitle":"Pilot development stages","stages":[{"title":"Community research","status":"Completed","body":"Village engagement, interviews and surveys (May 2025)."},{"title":"Prototype & validation","status":"Completed","body":"Sun-tracking rig built; design input gathered from the community."},{"title":"Site & load assessment","status":"Next","body":"Confirm site, solar resource and household and productive demand."},{"title":"System design & approvals","status":"Upcoming","body":"Engineer the hub; engage the relevant authorities."},{"title":"Funding & procurement","status":"Upcoming","body":"Secure pilot capital and source equipment."},{"title":"Build, connect & learn","status":"Upcoming","body":"Install, connect the first users, measure and improve."}]}'::jsonb, '{"anchor":"shurugwi"}'::jsonb, 'published', true, 0),
  ('503ab243-3fec-5d2d-9570-a878f51e5dbe', '65166520-c7eb-51d2-a894-956d912d7e2a', 'next_page', null, '{"kicker":"Next","title":"Our journey","line":"The road so far, and what comes next.","href":"/journey"}'::jsonb, '{}'::jsonb, 'published', true, 1),
  ('b0e44d00-a242-5712-b701-8cc2d62b5a3b', 'e4b91eb5-e756-5fcf-b122-800948b15f5c', 'timeline', null, '{"kicker":"Our journey","headline":"From an idea to a village, *step by step.*","intro":"Research, prototypes, recognition and preparation: the real path VoltageAfrica has taken since 2024, and the milestone we are working toward now."}'::jsonb, '{}'::jsonb, 'published', true, 0),
  ('8b5765b0-0521-52a7-8a46-5c57f32c1dcf', 'e4b91eb5-e756-5fcf-b122-800948b15f5c', 'next_page', null, '{"kicker":"Next","title":"Impact & recognition","line":"Recognition, press and community.","href":"/impact"}'::jsonb, '{}'::jsonb, 'published', true, 1),
  ('492a7097-4a77-5211-8e3c-9db9209c2446', 'a19ff43f-39ec-5161-881c-8f71f4dfc961', 'publications', null, '{"kicker":"Publications, recognition & impact","headline":"In the press, *on the record.*","intro":"Coverage, awards and reports, each linked to its original source.","spread":[{"image":{"id":"67b9c468-458b-588e-ac42-5e144ccd6db3","src":"/images/milestones/brics-summit-pretoria.jpg","alt":"Sean Mavhima with delegates at the BRICS+ Youth Innovation Summit in Pretoria, South Africa"},"caption":"BRICS+ Youth Innovation Summit, Pretoria: 2nd Place, Sustainable Development and Green Solutions.","date":"Apr 2026"},{"image":{"id":"d904095b-2121-57bd-80e8-ff6c1b220e12","src":"/images/milestones/hackatom-stage.jpg","alt":"Team presenting on stage at the Global HackAtom final"},"caption":"Global HackAtom final, Moscow: finalist.","date":"Sep 2025"},{"image":{"id":"880477fc-ed83-571d-96ad-e83d1b73ffaf","src":"/images/milestones/green-award-nairobi.jpg","alt":"Sean Mavhima receiving the Africa''s Net Green Leader Award in Nairobi"},"caption":"Africa’s Net Green Leader Award, Nairobi.","date":"Aug 2025"}],"communityKicker":"In the community · Kigali, Rwanda","communityTitle":"Building the next generation of *climate leaders.*","communityBody":"Our renewable energy education programme teaches primary and secondary students about renewable energy generation, climate change and conservation, including at Camp Kigali School. We run surveys before and after each lesson to measure what students learn.","communityImages":[{"image":{"id":"df03f173-41d0-595e-aae9-358cc22e559d","src":"/images/outreach/kigali-school-group.jpg","alt":"Students and the VoltageAfrica team outside a classroom after a renewable energy lesson in Kigali"}},{"image":{"id":"f767451a-2f11-5285-9723-6e3d9ac8dcbe","src":"/images/outreach/kigali-lesson.jpg","alt":"Students completing a learning survey during a lesson"}},{"image":{"id":"fe4ed70e-7393-5701-a6bb-6e6537ff5e24","src":"/images/outreach/kigali-classroom.jpg","alt":"A class gathered after a conservation and renewable energy lesson"}}]}'::jsonb, '{}'::jsonb, 'published', true, 0),
  ('7ff4eba7-f105-5916-a6bc-4c8ca8e24309', 'a19ff43f-39ec-5161-881c-8f71f4dfc961', 'awards', null, '{"kicker":"Awards & recognition","headline":"Recognised for the work, *not the promise.*","intro":"Prizes, selections and fellowships, each linked to its source where one exists."}'::jsonb, '{"background":"paper","anchor":"awards"}'::jsonb, 'published', true, 1),
  ('f1f2e2bd-443b-5d15-8f65-b1ea92808c5c', 'a19ff43f-39ec-5161-881c-8f71f4dfc961', 'next_page', null, '{"kicker":"Next","title":"About","line":"The people and principles behind it.","href":"/about"}'::jsonb, '{}'::jsonb, 'published', true, 2),
  ('67e7a96f-10bd-5061-9ca9-8ac0f33c75ce', '3b1ab4fd-6c30-5c31-be01-bf4c3ebb71fd', 'page_intro', null, '{"kicker":"About","headline":"The people and *principles behind it.*","intro":"A venture founded in rural Zimbabwe, built by a team across Zimbabwe, Rwanda and Kenya, and guided by six commitments.","index":[{"label":"The founder","anchor":"founder"},{"label":"The team","anchor":"team"},{"label":"Our principles","anchor":"principles"}],"image":{"id":"bf957e5e-65d4-577b-adcc-317dd0fa6439","src":"/images/milestones/green-generation-team.jpg","alt":"Four young people in Green Generation Initiative t-shirts holding tree seedlings in a forest clearing"},"imageCaption":"Tree planting with the Green Generation Initiative. Energy access and environmental care go together.","imagePosition":"50% 35%"}'::jsonb, '{}'::jsonb, 'published', true, 0),
