  ('eef01a37-8f88-50a3-bf6c-b3d9fa417cc3', '3b1ab4fd-6c30-5c31-be01-bf4c3ebb71fd', 'principles', null, '{"kicker":"Our principles","headline":"How we *build.*","intro":"Six commitments that shape every design decision, from the first site survey to the hundredth hub.","image":{"id":"274b70ee-282f-56a1-b526-56d3da1226ac","src":"/images/landscape/chiremba-rocks.jpg","alt":"Granite boulders naturally balanced on top of one another at Chiremba"}}'::jsonb, '{"anchor":"principles"}'::jsonb, 'published', true, 2),
