  ('672e101d-6b08-53bd-b99e-cd2cfe8d5d8e', '177bd0af-7d32-5472-9ca6-987f58ab3492', 'contact', null, '{"kicker":"Contact & partnerships","headline":"Let’s build what *comes next.*","intro":"We are preparing our first pilot and looking for people and organisations who want to help build intelligent energy infrastructure for rural Africa.","audiences":["Energy & infrastructure partners","Technology partners","Development organisations","Investors & funders","Research institutions","Engineers","Rural development organisations","Agricultural partners","Climate innovators"],"detailsTitle":"Reach us directly","formTitle":"Send a message","formDescription":"","submitLabel":"Send message","successTitle":"Message received.","successMessage":"Your message has been received. Thank you for contacting VoltageAfrica.","nextStep":{"label":"Explore our technology","href":"/technology"},"privacyNote":"We use your details only to reply to this message.","pathwaysTitle":"Other ways to work with us","pathways":[{"title":"Partner with us","body":"For organisations and collaborators.","href":"/partner"},{"title":"Support our work","body":"Funding, equipment or expertise.","href":"/support"}],"image":{"id":"9312dba9-831c-5676-a6ce-340875d38954","src":"/images/founder/sean-field.jpg","alt":"Sean Mavhima planting a tree in dense green bush"},"imageCaption":"Sean Mavhima, founder of VoltageAfrica, in the field.","imagePosition":"50% 40%"}'::jsonb, '{}'::jsonb, 'published', true, 0),
  ('dac75cbf-d58e-50c7-af4e-30451f139c8d', '894da38a-92f3-5bc8-b4a0-2e05ad3d58ac', 'partnership', null, '{"kicker":"Partner with VoltageAfrica","headline":"Build the grid *with us.*","intro":"We welcome partnerships that help advance accessible, intelligent and sustainable energy infrastructure for African communities.","body":"VoltageAfrica is at an early stage: validating our technology, preparing our first community pilot in Shurugwi, Zimbabwe, and building the relationships that will carry it to deployment. The right partners shape that work, from engineering and equipment to research, funding and community implementation.","partnerTypesTitle":"Who we work with","partnerTypes":["Energy companies and utilities","NGOs and development organisations","Governments and public institutions","Investors and funding organisations","Universities and research institutions","Technology and hardware companies","Solar equipment suppliers","Battery and energy storage companies","Engineering and technical partners","Community organisations","Corporate partners","Individual strategic collaborators"],"formTitle":"Propose a partnership","formDescription":"Tell us who you are and how you would like to collaborate. Every inquiry is read by our team.","submitLabel":"Send partnership inquiry","successTitle":"Inquiry received.","successMessage":"Thank you for reaching out to VoltageAfrica. Your partnership inquiry has been received. Our team will review your message and get back to you.","nextStep":{"label":"See the Shurugwi pilot","href":"/pilot"},"privacyNote":"We use your details only to respond to this inquiry. They are never shared or published.","consentLabel":"I agree to be contacted by VoltageAfrica about this partnership inquiry.","image":{"id":"67b9c468-458b-588e-ac42-5e144ccd6db3","src":"/images/milestones/brics-summit-pretoria.jpg","alt":"Sean Mavhima with delegates at the BRICS+ Youth Innovation Summit in Pretoria, South Africa"},"imageCaption":"Sean Mavhima with delegates at the BRICS+ Youth Innovation Summit, Pretoria, South Africa, April 2026.","imagePosition":"50% 30%"}'::jsonb, '{}'::jsonb, 'published', true, 0),
  ('fca17965-4197-51a5-a8c7-52ccec9714d9', 'a47afd98-427b-5847-a284-c50905ae7ba8', 'donate', null, '{"kicker":"Fund the pilot","headline":"Help switch on *Shurugwi''s first community grid.*","intro":"VoltageAfrica is preparing its first solar microgrid hub in Shurugwi, Zimbabwe, for villages the national grid has not reached. Contributions go toward the pilot: equipment, installation and the community work around it.","donateLabel":"Donate","pledgeLabel":"Pledge your support","otherWaysLabel":"Equipment, expertise or partnership","methodsNote":"","goalLabel":"toward the Shurugwi pilot hub","tiersTitle":"What your gift makes possible","trustTitle":"Where the money goes","trustNote":"Every contribution is used for VoltageAfrica''s pilot and the research behind it. We report progress publicly on this site as the hub moves from preparation to construction.","noLinkNote":"Online giving opens soon. Pledge now and we will contact you personally with how to give."}'::jsonb, '{"anchor":"donate"}'::jsonb, 'published', true, 0),
  ('ffe0e852-233e-5128-bf75-7d98a73d4963', 'a47afd98-427b-5847-a284-c50905ae7ba8', 'support', null, '{"kicker":"Support VoltageAfrica","headline":"Help power the *first community grid.*","intro":"Support can help us advance renewable energy access, develop intelligent energy infrastructure, validate our solutions and, in time, deploy community microgrids.","body":"Whether you can offer funding, equipment, technical expertise or institutional backing, tell us what you have in mind. We will follow up personally to see how your contribution can make the most difference.","areasTitle":"Where support goes","areas":[{"title":"Community energy pilot development","body":"Preparing and building the first hub in Shurugwi, Zimbabwe."},{"title":"Solar panels and energy equipment","body":"Generation hardware for testing and for the pilot site."},{"title":"Battery storage","body":"Evening and overnight supply, and reserve for cloudy days."},{"title":"Engineering and research","body":"Site assessment, system design and field measurement."},{"title":"Technology development","body":"Monitoring, control and the intelligence layer of the hub."},{"title":"Rural community energy initiatives","body":"Engagement, education and outreach with communities."},{"title":"Productive-use energy solutions","body":"Milling, irrigation and cold storage that create income."}],"noticeTitle":"How this works","notice":"This form is a support inquiry, not a payment. VoltageAfrica does not process payments or donations on this website. Submitting the form does not commit you to anything: we will contact you directly to discuss your proposed contribution and agree the next steps together.","paymentNote":"Submitting this form does not make a payment. We will contact you to coordinate your proposed contribution.","formTitle":"Offer your support","formDescription":"Share what you would like to contribute. Amounts are optional and only help us plan.","submitLabel":"Send support inquiry","successTitle":"Thank you.","successMessage":"Thank you for wanting to support VoltageAfrica''s mission. Your contribution inquiry has been received. We will contact you to discuss the next steps.","nextStep":{"label":"Read about our vision","href":"/vision"},"privacyNote":"We use your details only to follow up on this inquiry. They are never shared or published.","consentLabel":"I agree to be contacted by VoltageAfrica about this support inquiry.","image":{"id":"832709ee-0938-5546-a656-1d4d78197041","src":"/images/outreach/kigali-courtyard.jpg","alt":"Students and teachers gathered outside a brick school building in Kigali after a VoltageAfrica lesson"},"imageCaption":"Students and teachers after a VoltageAfrica climate education session in Kigali, Rwanda. Community energy education is one of the areas support makes possible.","imagePosition":"50% 72%"}'::jsonb, '{}'::jsonb, 'published', true, 1),
  ('4ddfbd7f-4fab-566c-8b08-6e3ca9ee9d2b', '2abe12b1-b67f-515b-b8e6-86aed89cabc7', 'page_intro', null, '{"kicker":"Funders & press","headline":"Everything you need to *evaluate VoltageAfrica.*","intro":"Key facts, our research report, logos, photographs and ready-to-use descriptions, in one place. Figures link to their source or to our own research.","index":[{"label":"At a glance","anchor":"facts"},{"label":"Documents, logos & photographs","anchor":"downloads"},{"label":"About VoltageAfrica, ready to use","anchor":"about-texts"},{"label":"Recognition","anchor":"recognition"}]}'::jsonb, '{}'::jsonb, 'published', true, 0),
  ('b6b50171-ad8a-5656-9ee0-f9cc26627c4a', '2abe12b1-b67f-515b-b8e6-86aed89cabc7', 'key_facts', null, '{"kicker":"At a glance","headline":"Where VoltageAfrica *stands today.*","items":[{"label":"First pilot hub","value":"In preparation","detail":"Shurugwi, Midlands Province, Zimbabwe. Not yet operational.","href":"/pilot"},{"label":"Community research","value":"5 villages","detail":"23 household interviews, 6 community leaders and 27 surveys (May 2025).","href":"/documents/voltageafrica-shurugwi-validation-report-2025.pdf"},{"label":"Prototype","value":"Built & tested","detail":"Sun-tracking rig: four 15 W modules steered by a light sensor (2025).","href":"/technology#approach"},{"label":"Team","value":"4 people","detail":"Working across Zimbabwe, Rwanda and Kenya.","href":"/about"},{"label":"Recognition","value":"5 awards","detail":"Prizes and selections, including 2nd place at the BRICS+ Youth Innovation Summit 2026.","href":"/impact#awards"},{"label":"Building since","value":"2024","detail":"From an energy-trading prototype to field research and hardware.","href":"/journey"}],"note":"Status as of November 2026. The pilot hub is in preparation; VoltageAfrica does not yet operate a microgrid."}'::jsonb, '{"anchor":"facts","background":"paper"}'::jsonb, 'published', true, 1),
  ('d7f34d5b-4536-5658-8a06-aeec9deb3d41', '2abe12b1-b67f-515b-b8e6-86aed89cabc7', 'downloads', null, '{"kicker":"Downloads","headline":"Documents, logos *and photographs.*","intro":"Download what you need. Documents marked “on request” are shared directly by email, so we can send the current version.","items":[{"group":"Documents","title":"Shurugwi community outreach & validation report","description":"Five villages, 23 household interviews, 6 community leaders and 27 surveys. May 2025.","href":"/documents/voltageafrica-shurugwi-validation-report-2025.pdf","meta":"PDF · 3 pages · 216 KB"},{"group":"Documents","title":"Pitch deck","description":"Our presentation for investors, funders and partners.","href":"","meta":""},{"group":"Documents","title":"Venture overview & impact report","description":"The venture in detail: approach, technology and intended impact.","href":"","meta":""},{"group":"Documents","title":"Venture description","description":"A short written summary of VoltageAfrica.","href":"","meta":""},{"group":"Brand","title":"Logo pack","description":"Horizontal, stacked, symbol and wordmark logos in every tone, with usage guidance.","href":"/brand/voltageafrica-logo-pack.zip","meta":"ZIP · SVG + PNG · 1.6 MB"},{"group":"Brand","title":"Primary logo","description":"Horizontal logo for light backgrounds.","href":"/brand/logo-horizontal-primary.svg","meta":"SVG · 19 KB"},{"group":"Photographs","title":"Sean Mavhima, founder","description":"In the field, Zimbabwe.","href":"/images/founder/sean-field.jpg","meta":"JPG · 2200 × 1467 · 688 KB"},{"group":"Photographs","title":"Sun-tracking prototype, 2025","description":"Four 15 W modules steered by a central light sensor.","href":"/images/prototype/tracker-array.jpg","meta":"JPG · 1916 × 2000 · 574 KB"},{"group":"Photographs","title":"Climate education session, Kigali","description":"Students and the VoltageAfrica team after a renewable energy lesson.","href":"/images/outreach/kigali-school-group.jpg","meta":"JPG · 2000 × 1125 · 391 KB"}],"requestSubject":"Document request","note":"Photographs: © VoltageAfrica. You may use them in coverage of VoltageAfrica with the credit “VoltageAfrica”; for any other use, please ask. Please follow the logo guidance in the pack."}'::jsonb, '{"anchor":"downloads"}'::jsonb, 'published', true, 2),
  ('d8717e15-565a-5695-a226-f0e12ec8a16e', '2abe12b1-b67f-515b-b8e6-86aed89cabc7', 'boilerplate', null, '{"kicker":"Ready to use","headline":"About VoltageAfrica, *in your word count.*","intro":"Copy any of these into an article, a programme application or an introduction. Each one is accurate as of November 2026.","blocks":[{"label":"One line","text":"VoltageAfrica designs intelligent solar microgrids for rural communities beyond the reach of the national grid, starting with a pilot hub in Shurugwi, Zimbabwe."},{"label":"About · short","text":"VoltageAfrica is building intelligent renewable energy infrastructure for rural Africa: community solar microgrids that combine generation, battery storage, smart metering and distribution, designed around the homes, schools and enterprises they serve. Founded by Sean Mavhima, the team works across Zimbabwe, Rwanda and Kenya. Its first pilot hub, in Shurugwi, Zimbabwe, is in preparation."},{"label":"About · long","text":"VoltageAfrica is building intelligent renewable energy infrastructure for communities the national grid has not reached. In rural Zimbabwe, only 23.4% of residents have grid electricity (ZimStat, 2022 census).\n\nEach VoltageAfrica hub is a complete local energy system: solar generation, battery storage, smart metering and a low-voltage network, sized around productive uses such as milling, irrigation and cold storage as well as homes, because income is what makes energy access last.\n\nThe venture began with research: in May 2025 the team engaged five villages in Shurugwi, held 23 household interviews and 6 interviews with community leaders, and collected 27 surveys. It has built and tested a sun-tracking prototype, and its first pilot hub in Shurugwi is in preparation. VoltageAfrica placed second in Sustainable Development and Green Solutions at the BRICS+ Youth Innovation Summit 2026 and was a finalist in the Global HackAtom International Student Championship."},{"label":"Founder bio","text":"Sean Mavhima is the founder and CEO of VoltageAfrica. He grew up in rural Zimbabwe, where access to electricity, textbooks and digital tools was a daily struggle. A Mastercard Foundation Scholar at the University of Rwanda, he works where energy, intelligent systems and entrepreneurship meet, building the infrastructure he grew up without for the communities that still live without it."}],"contactTitle":"Press & funder contact","contactNote":"We usually reply within a few working days."}'::jsonb, '{"anchor":"about-texts","background":"paper"}'::jsonb, 'published', true, 3),
  ('c577d8e1-6ac6-5fac-9439-e1f794152987', '2abe12b1-b67f-515b-b8e6-86aed89cabc7', 'awards', null, '{"kicker":"Recognition","headline":"Prizes, selections *and fellowships.*","intro":"Each linked to its source where one exists."}'::jsonb, '{"anchor":"recognition","background":"parchment"}'::jsonb, 'published', true, 4),
  ('fc230a59-6972-5cd7-997b-77c213e8b699', '27e84d58-5765-5bd3-b317-d34fbbb13a58', 'energy_lab', null, '{"kicker":"VoltageAfrica AI Energy Lab","headline":"Intelligent energy. *Simulated, explored, explained.*","intro":"Step inside a simulated community microgrid. Change the weather, the equipment and the community''s demand, then watch how an intelligent energy manager decides what to supply, when, and what to protect, and why.","paused":false,"pausedMessage":"The Energy Lab is being updated and will be back shortly.","disclaimer":"Everything in the Energy Lab is a simulation of a conceptual hub. VoltageAfrica does not yet operate a microgrid, and nothing here is live data, a field measurement or a validated forecast. The lab does not control any equipment.","features":[{"title":"A real simulator","body":"Sun position, weather, temperature, battery efficiencies and eleven community loads, every 15 minutes."},{"title":"An optimiser","body":"Schedules pumping and milling into solar surplus and protects a reserve for the clinic."},{"title":"A copilot","body":"Explains the system and runs what-if simulations, grounded in the simulator''s own numbers."}],"defaultPreset":"sunny","defaultLevel":"explore","presets":[],"households":60,"solarKwp":30,"batteryKwh":80,"reservePct":25,"education":[{"title":"Why a battery reserve?","body":"Without load management, an empty battery switches off the whole village at once, the clinic included. Holding back a reserve that only critical services may use keeps the vaccine fridge and the lights on when everything else must wait."},{"title":"Why move the mill?","body":"Solar power is free at midday and expensive at night, because night-time energy has to pass through the battery, losing about 10% and wearing it out. Running flexible machines in the sun saves the battery for the evening."},{"title":"What intelligence cannot do","body":"Scheduling and prioritisation decide who gets the energy. They cannot create it. When demand exceeds what the sun and the battery can supply, the lab says so and shows what equipment would close the gap."}],"copilotOff":false,"copilotIntro":"Ask anything about the scenario on screen. The copilot reads the simulator''s numbers (generation, demand, battery, the optimiser''s recommendations, the forecast) and can run new what-if simulations. If the data cannot answer a question, it says so.","suggestedQuestions":["Why is the battery discharging?","What happens if it is cloudy for three days?","Can the system support 20 additional households?","What should we run during the solar peak?","Compare the baseline with the optimised system.","Explain this system to a non-engineer."]}'::jsonb, '{}'::jsonb, 'published', true, 0),
  ('ed2026ca-c11a-5937-a933-7af508a2b834', 'caf6303d-2ba8-5e37-a3fc-19af3cd1b340', 'page_intro', null, '{"kicker":"Privacy policy","headline":"Your information, *handled with care.*","intro":"What we collect through this website, why, who can see it, and the choices you have. Last updated 20 November 2026.","index":[]}'::jsonb, '{}'::jsonb, 'published', true, 0),
  ('7a312210-ad6b-54ec-b45a-c17f8ca06469', 'caf6303d-2ba8-5e37-a3fc-19af3cd1b340', 'rich_text', null, '{"kicker":"","headline":"","body":"<h2>Who we are</h2><p>This website is run by VoltageAfrica (“we”, “us”), a venture building renewable energy infrastructure, working across Zimbabwe, Rwanda and Kenya. For any question about your personal information, use our <a href=\"/contact\">contact page</a> or email the address shown there.</p><h2>What we collect</h2><p>We only collect what you choose to send us through the forms on this site:</p><ul><li><strong>Partnership inquiries:</strong> your name, organisation, email, country, partnership category, proposal and message, and optionally your phone number and website or LinkedIn address.</li><li><strong>Support inquiries:</strong> your name, email, country, the kind of support you are offering, an optional amount and currency, and your message. Submitting this form is not a payment, and we never ask for card or bank details on this site.</li><li><strong>Contact messages:</strong> your name, email, subject, inquiry category and message.</li></ul><p>To protect the forms from spam and abuse, we also store a one-way hash of the network address each submission came from, never the address itself. Our hosting provider keeps short-lived technical logs (for example the pages requested and the browser used) to run the site securely.</p><h2>Cookies and similar technologies</h2><p>We do not use advertising or analytics cookies, and we do not track you across other websites. Your browser remembers a few small preferences on your own device: whether you chose the film or the 3D view on the homepage and whether you have already seen its opening animation (both for the length of your visit), and whether you chose the light or dark theme (kept until you change it or clear your browser data). None of these are sent to us. Administrators who sign in to manage the site receive a sign-in cookie; visitors do not.</p><h2>How we use your information</h2><ul><li>to read and reply to your inquiry, and to follow up on a partnership, support offer or request you have made;</li><li>to keep records of those conversations;</li><li>to protect the site and its forms from abuse.</li></ul><p>We rely on your consent, which you give by ticking the consent box or by sending us a message, and on our legitimate interest in running and protecting the site. We do not sell your information, use it for automated decision-making or add you to a mailing list without asking.</p><h2>Who can see it</h2><p>Only VoltageAfrica’s administrators can see submissions. We use trusted service providers to operate the site: <strong>Supabase</strong> (secure database), <strong>Vercel</strong> (website hosting) and <strong>Resend</strong> (sending us a notification email when a submission arrives). They process data on our behalf and may store it on servers outside your country, under their own security and data-protection commitments. We share information with others only when the law requires it.</p><h2>How long we keep it</h2><p>We keep inquiries for as long as we need them to respond and to manage any relationship that follows. We review stored inquiries at least once a year and delete those we no longer need. You can ask us to delete yours at any time.</p><h2>Your rights</h2><p>You can ask to see the information we hold about you, to correct it, to delete it, or to withdraw your consent, and you can object to how we use it. Contact us and we will respond as quickly as we can, and within the time the law allows. You also have the right to complain to a data protection authority: in Zimbabwe, the Postal and Telecommunications Regulatory Authority (POTRAZ); in Rwanda, the National Cyber Security Authority; in Kenya, the Office of the Data Protection Commissioner; or the authority where you live.</p><h2>Security</h2><p>Submissions travel over an encrypted connection and are stored in a database that only signed-in administrators can read. No method of transmission or storage is completely secure, but we take reasonable steps to protect your information.</p><h2>Children</h2><p>Our forms are intended for adults. If you believe a child has sent us personal information, please contact us and we will delete it.</p><h2>Other websites</h2><p>This site links to other websites, such as news articles and photograph sources. Their privacy practices are their own.</p><h2>Changes to this policy</h2><p>We will update this page if the way we handle information changes. Last updated: 20 November 2026.</p>"}'::jsonb, '{"background":"paper"}'::jsonb, 'published', true, 1),
  ('e75af25f-fbae-5fef-bfe1-a321e2bdf17c', 'b2788bf2-d776-593b-9094-8b6941794b8b', 'page_intro', null, '{"kicker":"Projects","headline":"Work in *progress.*","intro":"Each VoltageAfrica initiative, its stage and its story.","index":[],"image":{"id":"c136d01c-ecd0-5093-b2b0-b0cb0e7d46f7","src":"/images/prototype/modules-side.jpg","alt":"Prototype solar modules seen from the side"},"imageCaption":"Prototype solar modules under test, 2025. Each project starts with something we can build and measure.","imagePosition":"50% 50%"}'::jsonb, '{}'::jsonb, 'published', true, 0),
  ('92c727c4-3b18-54d9-8247-56d48ce39f03', 'b2788bf2-d776-593b-9094-8b6941794b8b', 'projects_list', null, '{"kicker":"","headline":"","intro":""}'::jsonb, '{}'::jsonb, 'published', true, 1)
insert into public.timeline_milestones (id, title, event_date, date_label, description, category, image_id, image_position, link_url, link_label, is_upcoming, featured, sort_order, status) values
  ('f7c29b15-eddb-5902-9fb1-ec0b955bb7a8', 'Blockchain energy-trading prototype', '2024-09-01', 'Sep 2024', 'Early exploration of digitally enabled energy systems: a peer-to-peer trading prototype and interface designed so community members could share surplus solar power. The concept was presented at the ICP Hackathon in Rwanda.', 'Build', '134d457c-4001-563c-b203-3523df4250e1', '70% 40%', null, null, false, false, 0, 'published'),
  ('2bef1e12-9776-5cb3-b8ca-f604dc96de24', 'Customer interviews with rural households', '2024-12-01', 'Dec 2024', 'Community research to understand energy needs, lived experience, the cost of firewood and kerosene, and demand for an alternative.', 'Research', null, null, null, null, false, false, 1, 'published'),
  ('f5404f69-5a35-5e87-8982-0230d97675f8', 'Hardware prototype built and tested', '2025-03-01', 'Mar 2025', 'A sun-tracking solar rig: four 15 W modules around a light-dependent-resistor (LDR) sensor module that steers the array toward the strongest light.', 'Build', 'e24fa183-d39e-5832-a4ec-963c2187bdc4', '50% 50%', null, null, false, false, 2, 'published'),
  ('dbf8daf4-ac28-5d4a-99b9-ccbe3a5db276', 'Field research in five Shurugwi villages', '2025-05-01', 'May 2025', 'Engagement with Zura, Chinderera, Chinho, Mapako and Madungwe: 23 household interviews, 6 community leaders, and 27 completed surveys.', 'Research', null, null, null, null, false, false, 3, 'published'),
  ('681bc88b-9d7b-5c04-bc5f-378c6925c3d1', 'Green award in Kenya', '2025-08-01', 'Aug 2025', 'Green Generation Initiative''s Africa''s Net Green Leader Award, recognising youth-driven climate action through community-based initiatives and clean energy solutions. Nairobi, 15 August 2025.', 'Recognition', '880477fc-ed83-571d-96ad-e83d1b73ffaf', '60% 35%', 'https://tinyurl.com/3nb733hc', 'Green Generation Initiative', false, true, 4, 'published'),
  ('9040ef91-bffd-5d84-955b-6b325607939c', 'Rosatom Africa: Global HackAtom', '2025-12-15', 'Dec 2025', 'Finalist in the first Global HackAtom International Student Championship, after competing at the final in Moscow in September 2025. Recognised by Rosatom Africa on 15 December 2025.', 'Recognition', 'd904095b-2121-57bd-80e8-ff6c1b220e12', '72% 55%', 'https://www.facebook.com/share/p/1AXBa6ouSn/', 'Rosatom Africa', false, true, 5, 'published'),
  ('1decc028-b307-5d9c-9a37-5e8a43623f48', 'BRICS+ Youth Innovation Summit: 2nd Place', '2026-04-01', 'Apr 2026', 'Second place in Sustainable Development and Green Solutions at the BRICS+ Youth Innovation Summit in Pretoria, South Africa.', 'Recognition', '67b9c468-458b-588e-ac42-5e144ccd6db3', '50% 40%', 'https://www.heraldonline.co.zw/zim-student-shines-on-global-stage/', 'The Herald', false, true, 6, 'published'),
  ('7ae2a2c7-072b-54fa-9fc1-e1b8c5d19624', 'beVisioneers: The Mercedes-Benz Fellowship', '2026-07-01', 'Jul 2026', 'Selected for Cohort 4 of the global fellowship for young innovators building planet-positive solutions.', 'Programme', null, null, null, null, false, false, 7, 'published'),
  ('8832e6a4-836a-5cda-a907-f1b35b0e66da', 'UNITAR: Japan–Africa partnership programme', '2026-08-01', 'Aug 2026', 'Selected for a UNITAR programme on empowering youth and women through Japan–Africa public-private partnership, promoting TICAD9.', 'Programme', null, null, null, null, false, false, 8, 'published'),
  ('a2591010-2ac5-5fd9-8c15-17202d5ad60b', 'First pilot hub: Shurugwi', null, 'Next', 'Midlands Province, Zimbabwe. Taking the work from research and prototype to a first community microgrid. The pilot is in preparation and not yet operational.', 'Upcoming', null, null, '/pilot', 'See the pilot plan', true, true, 9, 'published')
