  ('0a0f8cce-f91d-5c6c-ac54-0e6d11dde524', 'Green Generation Initiative · Kenya', 'Africa''s Net Green Leader Award', null, '15 August 2025', 'https://tinyurl.com/3nb733hc', 'Recognised for leadership and impact in advancing environmental sustainability and youth-driven climate action through community-based initiatives and clean energy solutions.', 'Award', '880477fc-ed83-571d-96ad-e83d1b73ffaf', false, 3, 'published'),
  ('588f42c3-07dd-5c3a-8fd0-7ddea7647e6c', 'Jim Leech Mastercard Foundation Fellowship', '2024 Impact Report', null, 'Published 2025', 'https://tinyurl.com/k4feh3n3', 'Featured as a fellow contributing to leadership, community impact and sustainable development initiatives aligned with clean energy access, youth empowerment and social innovation.', 'Report', '1a270347-bc45-5ebe-8268-2f01b32cc1ac', false, 4, 'published'),
