insert into public.technology_items (id, image_id, status, kind, key, title, kicker, body, points, status_label, note, enables, sort_order) values
  ('74e00064-1a85-52f4-9601-d99671a2f83b', null, 'published', 'approach_step', 'sun', 'Sun', 'The resource', 'Southern Africa receives some of the strongest sunlight on Earth. It is free, local and arrives every day. The job is to capture it well.', '{}'::text[], null, null, null, 0),
  ('ee583ddd-1a2c-5afb-b3d0-a3bbfb968d34', null, 'published', 'approach_step', 'generation', 'Generation', 'Solar array', 'Panels turn sunlight into electricity. Our prototype uses a light-sensor tracker that turns the panels toward the sun through the day to harvest more of it.', '{}'::text[], null, null, null, 1),
  ('58f1e803-88a3-547a-8590-1fe56e228094', null, 'published', 'approach_step', 'storage', 'Storage', 'Battery bank', 'Daytime surplus is stored in batteries so power is still there at night, when households need it most.', '{}'::text[], null, null, null, 2),
  ('d5fbd793-d10e-5601-b688-3fa123dabf9b', null, 'published', 'approach_step', 'intelligence', 'Intelligence', 'Monitoring & control', 'Meters and sensors measure what is produced, stored and used. Over time, software learns the community''s patterns to keep the system balanced and healthy.', '{}'::text[], null, null, null, 3),
  ('800f2730-07e6-5e51-8295-1b5c7b377518', null, 'published', 'approach_step', 'distribution', 'Distribution', 'Local network', 'A protected low-voltage network carries power from the hub to homes, the school, the clinic and local businesses.', '{}'::text[], null, null, null, 4),
  ('eedcb872-b189-5750-ad79-7856091b9e5d', null, 'published', 'approach_step', 'community', 'Community', 'People & enterprise', 'Households pay for what they use through simple pay-as-you-go. Productive businesses become anchor customers that keep the hub viable.', '{}'::text[], null, null, null, 5),
  ('3747493d-ae18-5893-a972-771e5eaeab93', null, 'published', 'capability', 'light-sensor-sun-tracking', 'Light-sensor sun tracking', null, '', '{}'::text[], 'Prototyped', 'Built and tested on a 4 × 15 W module rig in 2025.', null, 0),
  ('4e9632b1-3f12-50e0-aa00-a6f3a5a63ada', null, 'published', 'capability', 'peer-to-peer-energy-trading', 'Peer-to-peer energy trading', null, '', '{}'::text[], 'Explored', 'Blockchain trading prototype and interface, 2024.', null, 1),
  ('df1f3664-b234-5459-97c6-f3cb817ffe8f', null, 'published', 'capability', 'energy-monitoring-and-smart-metering', 'Energy monitoring & smart metering', null, '', '{}'::text[], 'In design', 'Specified for the first pilot hub.', null, 2),
  ('5662d487-26f1-57de-9d91-1604ed4ab034', null, 'published', 'capability', 'pay-as-you-go-via-mobile-and-ussd', 'Pay-as-you-go via mobile & USSD', null, '', '{}'::text[], 'In design', 'Interest validated in community research.', null, 3),
  ('967d85cc-99ac-5e68-b1f8-2f84bf97c56c', null, 'published', 'capability', 'demand-forecasting', 'Demand forecasting', null, '', '{}'::text[], 'Planned', 'Requires real load data from a live hub.', null, 4),
  ('749f094e-bef7-52a2-9d3d-7d04b984638d', null, 'published', 'capability', 'storage-optimisation', 'Storage optimisation', null, '', '{}'::text[], 'Planned', 'Charge and discharge scheduling against forecasts.', null, 5),
  ('23712ea6-2312-552d-920e-5193eb69ffb4', null, 'published', 'capability', 'predictive-maintenance', 'Predictive maintenance', null, '', '{}'::text[], 'Planned', 'Fault detection from inverter and battery telemetry.', null, 6),
  ('7779f70c-ee63-524d-b4f3-7938a9c26da8', null, 'published', 'capability', 'multi-microgrid-management', 'Multi-microgrid management', null, '', '{}'::text[], 'Long-term', 'One platform operating many hubs.', null, 7),
  ('c8746950-7078-5496-b197-994c3bb3330c', null, 'published', 'productive_use', 'irrigation', 'Irrigation', null, 'Solar water pumping lets smallholders grow beyond the rainy season and water livestock reliably.', '{}'::text[], null, null, 'More harvests, less risk', 0),
  ('8b79b9d0-9611-572d-913c-e59c393d5ad0', null, 'published', 'productive_use', 'milling', 'Agro-processing', null, 'Grain mills, hullers and oil presses add value to crops locally instead of transporting them to town.', '{}'::text[], null, null, 'Value stays in the village', 1),
  ('d1d0ef2c-9639-5f26-8609-eda81293259f', null, 'published', 'productive_use', 'cold', 'Cold storage', null, 'Cooling extends the life of produce, milk and fish, so farmers can sell when the price is right.', '{}'::text[], null, null, 'Less spoilage, better prices', 2),
  ('8adfe322-8267-5c9b-8cb1-a5d5f257b7c6', null, 'published', 'productive_use', 'business', 'Small enterprise', null, 'Barbers, tailors, welders, phone-charging and retail shops: daytime loads that use solar power when it is plentiful.', '{}'::text[], null, null, 'Daytime demand, local jobs', 3),
  ('c4bb34af-513d-5d0a-926f-3dcf4bb4b64e', null, 'published', 'productive_use', 'institutions', 'Community institutions', null, 'Schools and clinics need dependable power for lighting, devices, refrigeration and connectivity.', '{}'::text[], null, null, 'Anchor customers', 4),
  ('a1eb5e46-9635-5b77-a96f-80074682eeb7', null, 'published', 'microgrid_component', 'solar', 'Solar array', 'Generation', 'Photovoltaic cells turn sunlight directly into direct-current (DC) electricity. Output rises from dawn, peaks around midday and falls to zero at dusk; passing clouds cause short dips.', array['Single-axis trackers turn the panels to follow the sun from east to west. Scrub the time of day to watch them move.', 'VoltageAfrica''s prototype steers panels with a light-dependent-resistor (LDR) sensor that finds the brightest part of the sky.', 'The array is the microgrid''s only fuel source: no diesel, no fuel deliveries.']::text[], null, null, null, 0),
  ('2ac293be-f301-512a-9806-ff243a08563a', null, 'published', 'microgrid_component', 'inverter', 'Inverter & power station', 'Conversion & control', 'Panels and batteries work in DC. Homes and machines use alternating current (AC). The inverter converts between the two and keeps voltage and frequency stable.', array['Hybrid inverters decide, moment by moment, whether solar power goes to loads, into the battery, or both.', 'They form the local grid: a stable 230 V AC supply that appliances can rely on.', 'Protection gear here isolates faults so one problem cannot take down the whole network.']::text[], null, null, null, 1),
  ('e987b962-5c33-52cd-a8dd-df6f7ea31ead', null, 'published', 'microgrid_component', 'battery', 'Battery energy storage', 'Storage', 'Sunlight arrives in the day; demand peaks after dark. Batteries store the midday surplus and release it in the evening and overnight.', array['The status strip on the container shows the modelled state of charge: green while charging, amber while discharging.', 'A battery management system watches cell temperatures, voltages and cycles to protect battery health.', 'Keeping a reserve margin means the community still has power after a cloudy day.']::text[], null, null, null, 2),
  ('6704621a-49f3-5b68-9383-578f671cac35', null, 'published', 'microgrid_component', 'distribution', 'Distribution network', 'Delivery', 'A low-voltage network of poles and conductors carries power from the hub to every connection: homes, the school, workshops and the water pump.', array['Breakers and fuses at the hub and along the line protect people and equipment.', 'Lines are sized for future growth, so more homes and businesses can connect later.', 'Toggle the energy flow to see AC power (green) travelling out along the network.']::text[], null, null, null, 3),
  ('a537b8be-9f87-5de9-83fc-49f02c2337b1', null, 'published', 'microgrid_component', 'household', 'Connected home', 'Everyday life', 'A connected household gets reliable power for lights, phone charging, a radio or television, a fan, and eventually a fridge, replacing candles, kerosene and long trips to charge a phone.', array['Evening light extends the day for study, work and family.', 'Phone charging at home keeps families connected to markets and mobile money.', 'Cleaner air indoors: no kerosene smoke.']::text[], null, null, null, 4),
  ('db64898e-f6ee-5b32-a2d4-a057f2fb8212', null, 'published', 'microgrid_component', 'school', 'School', 'Community institution', 'Schools need lighting, devices and connectivity. Reliable power makes digital learning and evening classes possible, and a school is a stable anchor customer for the hub.', array['Daytime loads line up with peak solar output: efficient for the system.', 'Clinics have similar needs, plus refrigeration for vaccines and medicines.', 'Schools we visited in Shurugwi, including Chinho Primary School, were interested in off-grid solar.']::text[], null, null, null, 5),
  ('4e6c79fe-27c9-50c4-ba25-7be6a5084fdf', null, 'published', 'microgrid_component', 'productive', 'Mill & cold room', 'Productive use', 'A grain mill and a cold room turn electricity into income: processing crops locally and keeping produce fresh until it can be sold at a fair price.', array['Productive loads are scheduled in daylight hours, using solar power directly when it is most abundant.', 'Selling energy for productive use is VoltageAfrica''s second revenue stream in development.', 'Local value-addition keeps more money circulating in the community.']::text[], null, null, null, 6),
  ('618ed725-c7fd-5495-84d5-3499cd2d629b', null, 'published', 'microgrid_component', 'water', 'Solar water pumping', 'Agriculture', 'A pump lifts water to an elevated tank that feeds irrigation and livestock. The tank stores water the way the battery stores energy.', array['Pumping runs during the sunniest hours, with no battery needed.', 'Irrigation can extend growing beyond the rainy season.', 'Water storage gives farmers a buffer through dry spells.']::text[], null, null, null, 7),
  ('cabbb238-55ef-537b-a290-cadf91d72d0a', null, 'published', 'microgrid_component', 'business', 'Community businesses', 'Enterprise', 'Shops, barbers, tailors and phone-charging kiosks can trade longer and offer new services once they have reliable power.', array['Refrigerated drinks, power tools and sewing machines open new income streams.', 'Businesses are daytime customers that balance household evening demand.', 'Reliable supply lowers the cost of running a diesel generator, or replaces it entirely.']::text[], null, null, null, 8),
  ('7e3753d4-0827-54e9-a5ff-ccf7e8c11160', null, 'published', 'microgrid_component', 'meters', 'Smart meters & monitoring', 'Energy intelligence', 'Every connection has a meter. Together with sensors at the hub, they show what is generated, stored and used, and they make pay-as-you-go billing possible.', array['Prepaid credit can be topped up by mobile money or USSD on a basic phone.', 'Data from meters and the battery system feeds forecasting and maintenance planning.', 'Smart metering is in design for our first pilot; forecasting and optimisation are planned to follow.']::text[], null, null, null, 9)
insert into public.principles (id, title, body, sort_order, status) values
  ('5befdc5f-7cac-5703-bfbe-903b4e4c6404', 'Energy access first', 'Technology only matters when it reliably serves people.', 0, 'published'),
  ('1b40cfd4-7efc-50ab-8a88-6a32fb09e8d9', 'Built for the realities of Africa', 'We design for affordability, heat and dust, patchy connectivity, local maintenance and what communities actually need.', 1, 'published'),
  ('b2826a35-9cfa-5fdb-ada2-7b5a4bdc2223', 'Intelligence with purpose', 'We use data, automation and AI only where they improve performance, affordability, reliability or decisions.', 2, 'published'),
  ('42234a5d-b81f-5e9f-90d9-e457ae02496d', 'Productive communities', 'Energy should power enterprise, jobs and local productivity, not only light bulbs.', 3, 'published'),
  ('ea235c60-0a48-54a8-9268-8c9c06a23a68', 'Responsible infrastructure', 'Safety, lifecycle impact, maintenance, battery recycling and long-term resilience are part of the design from day one.', 4, 'published'),
  ('44c57b1f-e08a-5128-9b50-8d64cdfdd794', 'Built to scale', 'Systems, software and processes that can be replicated and improved from one community to the next.', 5, 'published')
insert into public.people (id, name, role, country, bio, quote, quote_source_label, quote_source_url, image_id, social_links, is_founder, sort_order, status) values
  ('9f7972dc-d71a-5da1-8d49-75f77b9b04c4', 'Sean Mavhima', 'Founder & CEO', 'Zimbabwe', '<p>Sean Mavhima grew up in rural Zimbabwe, where access to electricity, textbooks and digital tools was a daily struggle. The Covid-19 years sharpened his sense of the digital divide in remote areas, and of how much depends on reliable power.</p><p>A Mastercard Foundation Scholar at the University of Rwanda, he works where energy, intelligent systems and entrepreneurship meet. VoltageAfrica is his attempt to build the infrastructure he grew up without, designed for the communities that still live without it.</p>', 'These challenges ignited a deep drive in me to acquire skills that would allow me to lead change for my people.', 'Sean Mavhima, in The Herald, 3 May 2025', 'https://www.heraldonline.co.zw/lighting-the-path-for-africas-future/', '86312ded-42da-5453-940c-fa281b97683c', '[{"label":"LinkedIn","url":"https://www.linkedin.com/in/sean-mavhima/"},{"label":"Instagram","url":"https://www.instagram.com/sean_mavhimaa/"},{"label":"Facebook","url":"https://www.facebook.com/sean.mavhima.50/"}]'::jsonb, true, 0, 'published'),
  ('f5054e12-a842-5ea1-8a98-4737544b1d8d', 'Patience Gasaro', 'Co-Founder & CTO', 'Rwanda', '', null, null, null, null, '[]'::jsonb, false, 1, 'published'),
  ('e8fb6ece-eaf3-52ef-8210-3f709baba90a', 'Mary Suzane', 'Marketing Lead', 'Kenya', '', null, null, null, null, '[]'::jsonb, false, 2, 'published'),
  ('8ea6b89a-aa16-5874-b051-0f2c0009249e', 'Peace de Joie Agasaro', 'Community Engagement Lead', 'Rwanda', '', null, null, null, null, '[]'::jsonb, false, 3, 'published')
insert into public.projects (id, name, slug, summary, body, stage, location, cover_image_id, categories, featured, sort_order, status) values
  ('3ce14218-d74b-5eb1-b455-668a35306248', 'Shurugwi pilot hub', 'shurugwi-pilot-hub', 'VoltageAfrica''s proposed first community microgrid, in Shurugwi, Midlands Province, Zimbabwe. In preparation, not yet operational.', '<p>The Shurugwi pilot will be VoltageAfrica''s first community energy hub. In May 2025 we engaged five villages (Zura, Chinderera, Chinho, Mapako and Madungwe) through local leadership, held 23 household interviews and 6 interviews with community leaders, and received 27 completed surveys.</p><h3>What communities told us</h3><ul><li>Households said they could pay for energy on a pay-as-you-go basis, at up to about US$10 a month.</li><li>Communities prefer a shared, community-owned energy hub to buying individual home systems.</li><li>Strong interest in USSD payments, which work on basic phones without data.</li><li>Support for clean cooking alongside electricity: firewood dependence is driving deforestation.</li><li>Schools visited, including Chinho Primary School, were interested in off-grid solar.</li></ul><h3>Status</h3><p>The pilot is in preparation. Site and load assessment comes next; specifications will follow that assessment.</p>', 'In preparation', 'Shurugwi, Midlands Province, Zimbabwe', null, array['Solar microgrid', 'Rural electrification', 'Pilot']::text[], true, 0, 'published')
